namespace log4net{public interface ILog{void Error(object value);void Info(object value);void DebugFormat(string format,params object[] args);}public class Log:ILog{public void Error(object value)=>Host.C.Event("error:"+value);public void Info(object value)=>Host.C.Event("info:"+value);public void DebugFormat(string format,params object[] args)=>Host.C.Event("debug:"+string.Format(format,args));}public static class LogManager{public static ILog GetLogger(Type type)=>new Log();}}
namespace OpenSim.Server.Base{public static class ServerUtils{public static T LoadPlugin<T>(string module,object[] args){Host.C.Event("load:"+module);return Host.C.Load?(T)(object)Host.C.Service:default;}}}
namespace OpenSim.Framework{public static class Util{public static string UUIDZeroString="00000000-0000-0000-0000-000000000000";public static void FireAndForget(WaitCallback callback,object state,string name){Host.C.Event("post:"+name);Host.C.Jobs.Enqueue(()=>callback(state));}}}
namespace OpenSim.Region.Framework.Scenes{
 public class Info{public string RegionName{get{Host.C.Event("scene.name");return "Region";}}}
 public class Scene{public int Registered;public Info RegionInfo=new();public void RegisterModuleInterface<T>(T module){Host.C.Event("register");++Registered;}public T RequestModuleInterface<T>(){Host.C.Event("scene.cache");return Host.C.CacheMode==0?default:(T)(object)Host.C.Cache;}}
