static class Host{public static Context C;public static string Hex(string text)=>Convert.ToHexString(Encoding.UTF8.GetBytes(text)).ToLowerInvariant();}
class Context{
 public string Trace="",Failure;public AssetBase A=new(),B=new();public int CacheMode,ServiceMode;public bool Load=true;public Queue<Action> Jobs=new();public Cache Cache;public Service Service;
 public Context(){A.Data=new byte[]{1,2};B.Data=new byte[]{3,4};A.ID="00000000-0000-0000-0000-000000000001";B.ID="00000000-0000-0000-0000-000000000002";}
 public void Event(string name){Trace+=name+";";if(name==Failure)throw new Exception("injected");}public string Name(AssetBase a)=>a==null?"N":ReferenceEquals(a,A)?"A":ReferenceEquals(a,B)?"B":"?";public string Bytes(byte[] b)=>b==null?"N":Convert.ToHexString(b).ToLowerInvariant();
}
class Cache:IAssetCache{
 public AssetBase Held;public Cache(){Held=Host.C.B;}public void CacheNegative(string id)=>Host.C.Event("negative:"+id);public void CacheAsset(AssetBase a,bool replace){Host.C.Event("cache:"+Host.C.Name(a)+":"+(replace?1:0));Held=a;}void IAssetCache.Cache(AssetBase a,bool replace)=>CacheAsset(a,replace);
 bool Read(string id,out AssetBase a,string op){var c=Host.C;c.Event(op+":"+id);a=c.CacheMode==1||c.CacheMode==4?Held:null;return c.CacheMode!=3&&c.CacheMode!=4;}public bool Get(string id,out AssetBase a)=>Read(id,out a,"get");public bool GetFromMemory(string id,out AssetBase a)=>Read(id,out a,"memory");public AssetBase GetCached(string id)=>null;public bool Check(string id)=>false;public void Expire(string id)=>Host.C.Event("expire:"+id);public void Clear(){}
}
class SharedCache:Cache,ISharedRegionModule{public string Name=>"Cache";public Type ReplaceableInterface=>null;public void Initialise(IConfigSource source){}public void Close(){}public void AddRegion(Scene scene){}public void RemoveRegion(Scene scene){}public void RegionLoaded(Scene scene){}public void PostInitialise(){}}
class Service:IAssetService{
 public Action<AssetBase> Pending;
 public AssetBase Get(string id){Host.C.Event("service.get:"+id);return Host.C.ServiceMode==1?null:Host.C.A;}
 public AssetBase Get(string id,string foreign,bool local)=>null;public AssetBase GetCached(string id)=>null;public AssetMetadata GetMetadata(string id)=>null;public byte[] GetData(string id)=>null;
 public bool Get(string id,object sender,AssetRetrieved callback){var c=Host.C;c.Event("service.async:"+id+":"+(sender??"N"));if(c.ServiceMode==4){Pending=a=>callback(id,sender,a);return true;}if(c.ServiceMode!=3){callback(id,sender,c.ServiceMode==1?null:c.A);if(c.ServiceMode==5)callback("second","secondSender",null);}return c.ServiceMode!=2&&c.ServiceMode!=3;}
 public void Get(string id,string foreign,bool local,SimpleAssetRetrieved callback)=>Host.C.Event("unexpected.simple");public bool[] AssetsExist(string[] ids){Host.C.Event("exists:"+ids.Length);return new[]{true,false};}public string Store(AssetBase a){Host.C.Event("service.store:"+Host.C.Name(a));return "stored";}public bool UpdateContent(string id,byte[] bytes){Host.C.Event("update:"+id+":"+Host.C.Bytes(bytes));return true;}public bool Delete(string id){Host.C.Event("delete:"+id);return true;}
}
class LocalAssetReference{
 static object Field(LocalAssetServicesConnector value,string name)=>typeof(LocalAssetServicesConnector).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);
 static string State(LocalAssetServicesConnector value)=>((bool)Field(value,"m_Enabled")?"1":"0")+(Field(value,"m_AssetService")!=null?"1":"0")+(Field(value,"m_Cache")!=null?"1":"0");
 static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var parts=line.Split(' ');var c=new Context{CacheMode=int.Parse(parts[0]),ServiceMode=int.Parse(parts[1]),Failure=parts[4]=="-"?"":parts[4]};Host.C=c;c.Cache=parts[2]=="1"?new SharedCache():new Cache();c.Service=new Service();var scene=new Scene();var connector=new LocalAssetServicesConnector();string result="",id="asset",zero=Util.UUIDZeroString;
 foreach(char op in parts[3]){string returned="-";try{switch(op){case 'I':case 'i':case 'E':case 'M':case 'N':connector.Initialise(new IniConfigSource("config-"+op+".ini"));break;case 'A':connector.AddRegion(scene);break;case 'R':connector.RegionLoaded(scene);break;case 'G':returned=c.Name(connector.Get(id));break;case 'Z':returned=c.Name(connector.Get(zero));break;case 'C':returned=c.Name(connector.GetCached(id));break;case 'T':var m=connector.GetMetadata(id);returned=m==null?"N":ReferenceEquals(m,c.A.Metadata)?"A":ReferenceEquals(m,c.B.Metadata)?"B":"?";break;case 'D':returned=c.Bytes(connector.GetData(id));break;case 'B':case 'b':returned=connector.Get(op=='B'?id:zero,"sender",(key,sender,a)=>c.Event("callback:"+key+":"+(sender??"N")+":"+c.Name(a)))?"1":"0";break;case 'S':case 's':connector.Get(op=='S'?id:zero,"https://ignored",true,a=>c.Event("simple:"+c.Name(a)));break;case 'X':returned=c.Name(connector.Get(id,"https://ignored",true));break;case 'O':case 'L':c.A.Local=op=='L';returned=connector.Store(c.A)??"N";break;case 'U':returned=connector.UpdateContent(id,new byte[]{9})?"1":"0";break;case 'd':returned=connector.Delete(id)?"1":"0";break;case 'H':returned="";foreach(bool b in connector.AssetsExist(new[]{id,zero}))returned+=b?'1':'0';break;case 'P':case 'Q':int n=op=='P'?Math.Min(1,c.Jobs.Count):c.Jobs.Count;while(n-->0)c.Jobs.Dequeue()();break;case 'K':c.Service.Pending?.Invoke(c.A);break;case 'V':c.Load=!c.Load;break;case 'W':c.ServiceMode=c.ServiceMode==1?0:1;break;case 'Y':c.CacheMode=c.CacheMode==1?2:1;break;case 'F':connector.RemoveRegion(scene);break;case 'J':connector.Close();connector.PostInitialise();break;}}catch{returned="EX";}result+=op+":"+Host.Hex(returned)+":"+State(connector)+":"+scene.Registered+":"+c.Jobs.Count+":"+c.Bytes(c.A.Data)+":"+c.Bytes(c.B.Data)+";";}
 Console.WriteLine(result+"|"+Host.Hex(c.Trace));c.Jobs.Clear();c.Service.Pending=null;}}
}
